class Solution {
public:
    long long maximumProfit(vector<int>& prices, int k) {
        int n = prices.size();
        const long long NEG = LLONG_MIN / 4;
        vector<long long> f(k + 1, 0), l(k + 1, NEG), s(k + 1, NEG);
        for (int i = 0; i < n; i++) {
            long long p = prices[i];
            vector<long long> nf(k + 1), nl(k + 1), ns(k + 1);
            for (int j = 0; j <= k; j++) {
                nf[j] = f[j];
                if (j > 0) {
                    long long closeL = (l[j - 1] == NEG) ? NEG : l[j - 1] + p;
                    long long closeS = (s[j - 1] == NEG) ? NEG : s[j - 1] - p;
                    nf[j] = max(nf[j], max(closeL, closeS));
                }
                nl[j] = (f[j] == NEG) ? NEG : max(l[j], f[j] - p);
                ns[j] = (f[j] == NEG) ? NEG : max(s[j], f[j] + p);
            }
            f.swap(nf);
            l.swap(nl);
            s.swap(ns);
        }
        return f[k];
    }
};
